import json
p='evidence/cross-agent-continuity-001/raw/session-002-pi.jsonl'
reads, writes, providers = set(), [], set()
for line in open(p):
    e=json.loads(line)
    s=json.dumps(e)
    for prov in ('opencode-cli','big-pickle','opencode/big-pickle'):
        if prov in s: providers.add(prov)
    def walk(o):
        if isinstance(o,dict):
            if o.get('name') in ('read','Read') :
                fp=o.get('arguments',{}).get('file_path') or o.get('input',{}).get('file_path') or o.get('arguments',{}).get('path')
                if fp: reads.add(fp)
            if o.get('name') in ('write','Write'):
                fp=o.get('arguments',{}).get('file_path') or o.get('input',{}).get('file_path')
                writes.append(fp)
            for v in o.values(): walk(v)
        elif isinstance(o,list):
            for v in o: walk(v)
    walk(e)
print("providers seen:", sorted(providers))
print("read targets containing semantic:", sorted(r for r in reads if 'semantic' in str(r)))
print("write targets:", sorted(set(str(w) for w in writes)))
EOF

